#!/usr/bin/env bash
set -euo pipefail
ROOT="$PWD/android_frota"
rm -rf "$ROOT"
mkdir -p "$ROOT/app/src/main/java/br/com/frotaemdia/app" "$ROOT/app/src/main/res/values" "$ROOT/app/src/main/assets"
cat > "$ROOT/settings.gradle" <<'EOF'
pluginManagement { repositories { google(); mavenCentral(); gradlePluginPortal() } }
dependencyResolutionManagement { repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS); repositories { google(); mavenCentral() } }
rootProject.name='FrotaEmDia'
include ':app'
EOF
cat > "$ROOT/build.gradle" <<'EOF'
plugins { id 'com.android.application' version '8.6.1' apply false }
EOF
cat > "$ROOT/app/build.gradle" <<'EOF'
plugins { id 'com.android.application' }
android {
  namespace 'br.com.frotaemdia.app'
  compileSdk 35
  defaultConfig { applicationId 'br.com.frotaemdia.app'; minSdk 24; targetSdk 35; versionCode 1; versionName '0.1.0' }
}
EOF
cat > "$ROOT/app/src/main/res/values/styles.xml" <<'EOF'
<resources><style name="AppTheme" parent="android:style/Theme.Material.Light.NoActionBar"><item name="android:fontFamily">sans</item><item name="android:statusBarColor">#0F172A</item><item name="android:navigationBarColor">#0F172A</item><item name="android:windowLightStatusBar">false</item></style></resources>
EOF
cat > "$ROOT/app/src/main/AndroidManifest.xml" <<'EOF'
<manifest xmlns:android="http://schemas.android.com/apk/res/android">
 <uses-permission android:name="android.permission.CAMERA"/><uses-permission android:name="android.permission.POST_NOTIFICATIONS"/>
 <uses-feature android:name="android.hardware.camera" android:required="false"/>
 <application android:theme="@style/AppTheme" android:label="Frota em Dia" android:allowBackup="true" android:supportsRtl="true">
  <activity android:name=".MainActivity" android:screenOrientation="portrait" android:exported="true"><intent-filter><action android:name="android.intent.action.MAIN"/><category android:name="android.intent.category.LAUNCHER"/></intent-filter></activity>
 </application>
</manifest>
EOF
cat > "$ROOT/app/src/main/java/br/com/frotaemdia/app/MainActivity.java" <<'EOF'
package br.com.frotaemdia.app;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.os.Bundle;import android.provider.MediaStore;import android.webkit.*;import java.text.SimpleDateFormat;import java.util.*;
public class MainActivity extends Activity {
 static final int PICK=42; ValueCallback<Uri[]> cb; Uri cameraUri;
 @Override public void onCreate(Bundle b){super.onCreate(b); if(android.os.Build.VERSION.SDK_INT>=23&&checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.CAMERA},10); if(android.os.Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},11); if(android.os.Build.VERSION.SDK_INT>=26){NotificationChannel c=new NotificationChannel("manut","Manutenção",NotificationManager.IMPORTANCE_HIGH);getSystemService(NotificationManager.class).createNotificationChannel(c);} WebView w=new WebView(this);setContentView(w);w.getSettings().setJavaScriptEnabled(true);w.getSettings().setDomStorageEnabled(true);w.addJavascriptInterface(new Bridge(),"Android");w.setWebViewClient(new WebViewClient());w.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> x,FileChooserParams p){cb=x;ContentValues cv=new ContentValues();cv.put(MediaStore.Images.Media.DISPLAY_NAME,"painel_"+System.currentTimeMillis()+".jpg");cv.put(MediaStore.Images.Media.MIME_TYPE,"image/jpeg");cameraUri=getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,cv);Intent cam=new Intent(MediaStore.ACTION_IMAGE_CAPTURE);cam.putExtra(MediaStore.EXTRA_OUTPUT,cameraUri);cam.addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_READ_URI_PERMISSION);Intent gal=new Intent(Intent.ACTION_GET_CONTENT);gal.setType("image/*");Intent ch=Intent.createChooser(gal,"Foto do hodômetro");ch.putExtra(Intent.EXTRA_INITIAL_INTENTS,new Intent[]{cam});startActivityForResult(ch,PICK);return true;}});w.loadUrl("file:///android_asset/index.html");}
 @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r!=PICK||cb==null)return;Uri[] out=null;if(c==RESULT_OK){if(d!=null&&d.getData()!=null)out=new Uri[]{d.getData()};else if(cameraUri!=null)out=new Uri[]{cameraUri};}cb.onReceiveValue(out);cb=null;}
 public class Bridge { @JavascriptInterface public void notifyMaintenance(String title,String text){Notification.Builder n=android.os.Build.VERSION.SDK_INT>=26?new Notification.Builder(MainActivity.this,"manut"):new Notification.Builder(MainActivity.this);n.setContentTitle(title).setContentText(text).setSmallIcon(android.R.drawable.stat_notify_more).setAutoCancel(true);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(500,n.build());}}
}
EOF
cat > "$ROOT/app/src/main/assets/index.html" <<'EOF'
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Frota em Dia</title><style>
:root{font-family:system-ui,-apple-system,sans-serif;color:#0f172a;background:#f1f5f9}*{box-sizing:border-box}body{margin:0}.top{background:#0f172a;color:white;padding:28px 20px 26px}.top b{font-size:25px}.top p{margin:5px 0 0;color:#cbd5e1}.wrap{max-width:650px;margin:auto;padding:16px}.card{background:white;border-radius:20px;padding:18px;margin-bottom:14px;box-shadow:0 8px 25px #0f172a12}.muted{color:#64748b;font-size:13px}.big{font-size:38px;font-weight:800;margin:4px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.pill{padding:12px;border-radius:14px;background:#f8fafc}.pill b{display:block;font-size:18px}.ok{border-left:6px solid #16a34a}.warn{border-left:6px solid #f59e0b}.bad{border-left:6px solid #dc2626}button{width:100%;border:0;border-radius:14px;padding:15px;font-weight:800;font-size:16px;margin-top:10px;background:#0f172a;color:white}.orange{background:#f59e0b;color:#111827}input{width:100%;padding:14px;border:1px solid #cbd5e1;border-radius:12px;font-size:16px;margin:6px 0 12px}label{font-size:13px;font-weight:700}dialog{border:0;border-radius:20px;width:calc(100% - 24px);max-width:520px;padding:20px}dialog::backdrop{background:#0008}.row{display:flex;gap:10px}.row>*{flex:1}.photo{display:block;border:2px dashed #94a3b8;border-radius:16px;padding:22px;text-align:center;background:#f8fafc}.photo input{display:none}.photo img{max-width:100%;border-radius:12px;margin-top:10px}.hide{display:none}.foot{text-align:center;color:#64748b;font-size:12px;padding:24px 8px 32px}.status{font-weight:800;font-size:18px}.smallbtn{background:#e2e8f0;color:#0f172a}.danger{color:#dc2626}.warning{color:#b45309}.good{color:#15803d}
</style></head><body><div class="top"><b>Frota em Dia</b><p>Controle de manutenção por quilometragem</p></div><main class="wrap"><section id="empty" class="card"><h2>Cadastre seu veículo</h2><p class="muted">Faça isso uma vez. Depois, basta mandar a foto do painel no fim do dia.</p><button onclick="openSetup()">Cadastrar veículo</button></section><section id="dash" class="hide"><div id="statusCard" class="card ok"><div class="muted">QUILOMETRAGEM ATUAL</div><div class="big"><span id="kmNow">0</span> km</div><div id="statusText" class="status good">Em dia</div><div class="grid" style="margin-top:14px"><div class="pill"><span class="muted">PRÓXIMA TROCA</span><b id="nextKm">0 km</b></div><div class="pill"><span class="muted">FALTAM</span><b id="remainKm">0 km</b></div></div></div><div class="card"><b id="vehicleTitle">—</b><p id="driverTitle" class="muted">—</p><button class="orange" onclick="openPhoto()">📷 Registrar KM do dia</button><button class="smallbtn" onclick="openMaint()">✓ Manutenção realizada</button></div><div class="card"><h3>Últimos registros</h3><div id="history" class="muted">Nenhum registro.</div></div></section><div class="foot">Desenvolvido Por Uriel da Fonseca Fortunato</div></main>
<dialog id="setup"><h2>Cadastro inicial</h2><label>Motorista<input id="driver" placeholder="Nome do motorista"></label><label>Placa<input id="plate" placeholder="ABC1D23" maxlength="7"></label><label>Modelo do veículo<input id="model" placeholder="Ex.: Fiat Strada"></label><label>KM atual<input id="current" type="number" inputmode="numeric"></label><label>KM da última troca de óleo<input id="lastOil" type="number" inputmode="numeric"></label><label>Intervalo da troca<input id="interval" type="number" value="10000" inputmode="numeric"></label><button onclick="saveSetup()">Salvar cadastro</button><button class="smallbtn" onclick="setup.close()">Cancelar</button></dialog>
<dialog id="photo"><h2>KM do dia</h2><p class="muted">Tire a foto do painel e confirme a quilometragem total.</p><label class="photo">📷 Abrir câmera<input id="imgInput" type="file" accept="image/*" capture="environment"><img id="preview" class="hide"></label><label>Quilometragem do painel<input id="daily" type="number" inputmode="numeric" placeholder="26430"></label><button class="orange" onclick="saveDaily()">Confirmar KM</button><button class="smallbtn" onclick="photo.close()">Cancelar</button></dialog>
<dialog id="maint"><h2>Manutenção realizada</h2><label>KM em que foi feita<input id="maintKm" type="number" inputmode="numeric"></label><label>Próximo intervalo<input id="maintInterval" type="number" value="10000" inputmode="numeric"></label><button onclick="saveMaint()">Registrar manutenção</button><button class="smallbtn" onclick="maint.close()">Cancelar</button></dialog>
<dialog id="result"><h2 id="resultTitle">Registro salvo</h2><p id="resultMsg"></p><button onclick="result.close()">OK</button></dialog>
<script>
const K='frotaEmDia01';let s=JSON.parse(localStorage.getItem(K)||'null');const $=id=>document.getElementById(id);function n(v){return Number(v)||0}function fmt(v){return Math.round(v).toLocaleString('pt-BR')}function save(){localStorage.setItem(K,JSON.stringify(s));render()}function openSetup(){setup.showModal()}function openPhoto(){daily.value=s.current||'';preview.classList.add('hide');preview.src='';imgInput.value='';photo.showModal()}function openMaint(){maintKm.value=s.current||'';maintInterval.value=s.interval||10000;maint.showModal()}function saveSetup(){let a={driver:driver.value.trim(),plate:plate.value.toUpperCase().replace(/[^A-Z0-9]/g,''),model:model.value.trim(),current:n(current.value),lastOil:n(lastOil.value),interval:n(interval.value),history:[]};if(!a.driver||!a.plate||!a.current||!a.lastOil||!a.interval)return alert('Preencha todos os campos.');s=a;save();setup.close()}function calc(){let next=s.lastOil+s.interval,rem=next-s.current;return{next,rem}}function saveDaily(){let km=n(daily.value);if(!imgInput.files[0])return alert('Tire a foto do painel antes de confirmar.');if(!km)return alert('Informe o KM do painel.');if(km<s.current)return alert('O KM não pode ser menor que o último registro ('+fmt(s.current)+' km).');if(km-s.current>2500&&!confirm('O veículo avançou '+fmt(km-s.current)+' km desde o último registro. Confirmar?'))return;s.current=km;s.history.unshift({type:'km',km,date:new Date().toLocaleString('pt-BR')});s.history=s.history.slice(0,30);save();photo.close();let c=calc();resultTitle.textContent=c.rem<0?'Manutenção vencida':c.rem<=500?'Manutenção próxima':'Registro salvo';resultMsg.innerHTML=c.rem<0?'Troca vencida em <b>'+fmt(Math.abs(c.rem))+' km</b>.':'Faltam <b>'+fmt(c.rem)+' km</b> para a próxima troca de óleo.';result.showModal();if(c.rem<=500&&window.Android){Android.notifyMaintenance(c.rem<0?'Troca de óleo vencida':'Manutenção próxima',c.rem<0?'Excedido em '+fmt(Math.abs(c.rem))+' km':'Faltam '+fmt(c.rem)+' km para a troca de óleo')}}function saveMaint(){let km=n(maintKm.value),i=n(maintInterval.value);if(!km||!i)return alert('Informe KM e intervalo.');if(km<s.current&&!confirm('O KM da manutenção é menor que o KM atual. Confirmar mesmo assim?'))return;s.lastOil=km;s.interval=i;if(km>s.current)s.current=km;s.history.unshift({type:'manut',km,date:new Date().toLocaleString('pt-BR')});save();maint.close();alert('Manutenção registrada. Próxima troca em '+fmt(km+i)+' km.')}imgInput.onchange=e=>{let f=e.target.files[0];if(f){preview.src=URL.createObjectURL(f);preview.classList.remove('hide')}};function render(){if(!s){empty.classList.remove('hide');dash.classList.add('hide');return}empty.classList.add('hide');dash.classList.remove('hide');kmNow.textContent=fmt(s.current);vehicleTitle.textContent=s.model+' • '+s.plate;driverTitle.textContent=s.driver;let c=calc();nextKm.textContent=fmt(c.next)+' km';remainKm.textContent=c.rem>=0?fmt(c.rem)+' km':'-'+fmt(Math.abs(c.rem))+' km';statusCard.className='card '+(c.rem<0?'bad':c.rem<=500?'warn':'ok');statusText.className='status '+(c.rem<0?'danger':c.rem<=500?'warning':'good');statusText.textContent=c.rem<0?'Manutenção vencida':c.rem<=500?'Atenção: manutenção próxima':'Em dia';history.innerHTML=s.history.length?s.history.map(x=>'<div style="padding:8px 0;border-bottom:1px solid #e2e8f0"><b>'+(x.type==='manut'?'Manutenção':'KM diário')+': '+fmt(x.km)+' km</b><br>'+x.date+'</div>').join(''):'Nenhum registro.'}render();
</script></body></html>
EOF
cd "$ROOT"
gradle --no-daemon :app:assembleDebug
mkdir -p "$GITHUB_WORKSPACE/out"
cp app/build/outputs/apk/debug/app-debug.apk "$GITHUB_WORKSPACE/out/Frota_em_Dia_v0.1.apk"
